let secrets;
try {
    secrets = JSON.parse(msg.payload);
} catch (e) {
    node.error('Could not parse secrets file: ' + e.message, msg);
    return null;
}
msg.secrets = secrets;
msg.job_started_at = new Date().toISOString();
const nowNs = Date.now() * 1000000;
msg.url = secrets.influxdb_url + '/api/v2/write?org=' + secrets.influxdb_org + '&bucket=' + secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = 'sync_job_runs,job_name=godaddy_restore,status=started value=1 ' + nowNs;
return msg;

// msg.payload here is the sqlite node's own result shape (array of row
// objects), confirmed against a real instance by sqlite_test_flow.json —
// NOT the HTTP-call msg.payload from earlier in this flow (that was
// already consumed by n_gr_write_start_http and isn't needed again).
const rows = Array.isArray(msg.payload) ? msg.payload : [];
const records = [];
let parseFailures = 0;
rows.forEach(row => {
    try {
        records.push(JSON.parse(row.data_json));
    } catch (e) {
        parseFailures++;
        node.warn('Skipping unparseable backup row (' + row.record_type + '/' + row.source_id + '): ' + e.message);
    }
});
msg.records = records;
msg.record_count = records.length;
msg.parse_failures = parseFailures;

if (!records.length) {
    msg.job_failed = true;
    msg.failure_code = 'unknown_error';
    msg.failure_detail = 'godaddy_backup table is empty — nothing to restore. Has godaddy_backup_flow.json run successfully at least once?';
    return [null, msg];
}
return [msg, null];

msg.url = msg.secrets.godaddy_base_url + '/api/bulk_restore.php';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Bearer ' + msg.secrets.godaddy_api_sync_token, 'Content-Type': 'application/json' };
msg.payload = JSON.stringify({ records: msg.records });
return msg;

const resp = msg.payload;
if (!resp || resp.error || resp.success !== true) {
    msg.job_failed = true;
    msg.failure_code = (resp && resp.error === 'unauthorized') ? 'godaddy_auth_failed'
        : (resp && resp.error) ? 'godaddy_error_response' : 'unknown_error';
    msg.failure_detail = resp ? JSON.stringify(resp).slice(0, 500) : 'empty response';
    return [null, msg];
}
node.warn('GoDaddy restore complete — records sent: ' + msg.record_count + ', counts: ' + JSON.stringify(resp.counts));
if (resp.unmatchedMeds && resp.unmatchedMeds.length) {
    node.warn('Restore: these medication names from the backup did not match anything currently in GoDaddy\'s Medications list: ' + resp.unmatchedMeds.join(', '));
}
msg.restore_counts = resp.counts;
return [msg, null];

const nowNs = Date.now() * 1000000;
const durationMs = Date.now() - new Date(msg.job_started_at).getTime();
msg.influx_finish_point = 'sync_job_runs,job_name=godaddy_restore,status=success record_count=' + (msg.record_count||0) + ',duration_ms=' + durationMs + ' ' + nowNs;
msg.sqlite_job = { job_name: 'godaddy_restore', mode: 'success', last_success: new Date().toISOString(), last_attempt: new Date().toISOString(), last_attempt_ok: 1 };
return msg;

const nowNs = Date.now() * 1000000;
const code = msg.failure_code || 'unknown_error';
const detail = (msg.failure_detail || '').replace(/([ ,="])/g, '\\$1');
msg.influx_finish_point = 'sync_job_runs,job_name=godaddy_restore,status=failed,failure_code=' + code + ' detail="' + detail + '" ' + nowNs;
msg.sqlite_job = { job_name: 'godaddy_restore', mode: 'failure', last_attempt: new Date().toISOString(), last_attempt_ok: 0, last_error: code + ': ' + (msg.failure_detail || '') };
node.warn('GoDaddy restore failed: ' + code + ' - ' + msg.failure_detail);
return msg;

msg.url = msg.secrets.influxdb_url + '/api/v2/write?org=' + msg.secrets.influxdb_org + '&bucket=' + msg.secrets.influxdb_bucket + '&precision=ns';
msg.method = 'POST';
msg.headers = { 'Authorization': 'Token ' + msg.secrets.influxdb_token, 'Content-Type': 'text/plain; charset=utf-8' };
msg.payload = msg.influx_finish_point;
return msg;

msg.topic = "CREATE TABLE IF NOT EXISTS job_status (" +
    "job_name TEXT PRIMARY KEY, last_success TEXT, last_attempt TEXT, " +
    "last_attempt_ok INTEGER, last_error TEXT, checkpoint TEXT, updated_at TEXT)";
return msg;

function esc(s) { return "'" + String(s).replace(/'/g, "''") + "'"; }
function sqlVal(v) { return (v === null || v === undefined) ? 'NULL' : (typeof v === 'number' ? v : esc(v)); }
const j = msg.sqlite_job;
const now = new Date().toISOString();
const cols = ['job_name', 'last_success', 'last_attempt', 'last_attempt_ok', 'last_error', 'checkpoint', 'updated_at'];
const vals = [j.job_name, j.last_success ?? null, j.last_attempt, j.last_attempt_ok, j.last_error ?? null, j.checkpoint ?? null, now];
const setClauses = ['last_attempt=excluded.last_attempt', 'last_attempt_ok=excluded.last_attempt_ok', 'updated_at=excluded.updated_at'];
if (j.mode === 'success') {
    setClauses.push('last_success=excluded.last_success', 'last_error=NULL');
} else {
    setClauses.push('last_error=excluded.last_error');
}
msg.topic = 'INSERT INTO job_status (' + cols.join(', ') + ') VALUES (' + vals.map(sqlVal).join(', ') + ') ' +
    'ON CONFLICT(job_name) DO UPDATE SET ' + setClauses.join(', ');
return msg;
